{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users instead of groups or roles can lead to excessive privileges and increased access management complexity."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc18-PassExistingRoleToNewGlueDevEndpoint-group" {
  name = "privesc18-PassExistingRoleToNewGlueDevEndpoint-group"
}

resource "aws_iam_group_membership" "privesc18-PassExistingRoleToNewGlueDevEndpoint-group-membership" {
  name  = "privesc18-PassExistingRoleToNewGlueDevEndpoint-group-membership"
  users = [aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name]
  group = aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name
}

resource "aws_iam_policy_attachment" "privesc18-PassExistingRoleToNewGlueDevEndpoint-attach-policy" {
  name       = "privesc18-PassExistingRoleToNewGlueDevEndpoint-attach-policy"
  groups     = [aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name]
  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn
}",
  "fix_summary": "Replaced aws_iam_user_policy_attachment with aws_iam_group and aws_iam_group_membership to attach the policy to a group instead of a user, reducing access management complexity."
}
